    x=Tokens::width*.79f;button("search","",{x,y,50,52},0,[this]{search();},false,true,false,true);draw().icon("search",x+25,y+25);button("settings","",{x+82,y,50,52},0,[this]{navigate("Settings");},false,true,false,true);draw().icon("settings",x+107,y+25);button("profile","",{x+164,y,50,52},0,[this]{navigate("My PS5");},false,true,false,true);draw().icon("profile",x+189,y+25);
    std::time_t now=std::time(nullptr);char clock[12];std::strftime(clock,sizeof(clock),"%H:%M",std::localtime(&now));draw().label(clock,Tokens::width-Tokens::safe-78,y+10,Tokens::body,Tokens::muted);
